// Every sentence and label the Hotspot Reports tab renders (hotspot-reports
// NFR-11, design-spec Content Notes).
//
// Count-bearing sentences are GENERATED by pure builders, never a hand-written
// table, and `hotspotReportsCopy.test.ts` sweeps every builder at counts of 0,
// 1 and 2 under the house agreement rules (ui.md v1.0.5): no count of one with
// a plural noun, no plural verb after a subject counted at one. No em dash, no
// literal non-ASCII character in this source (the ellipsis is written as an
// escape), American spelling. The tab is named only through `TAB_LABELS`.
//
// Strings that are the Life Lists pager's own (the paging controls) are
// re-exported from `lifeListsCopy.ts` rather than restated, so the two pagers
// cannot drift.

import { TAB_LABELS } from './tabLayout'
import type { KindReason } from './hotspotReportsKind'
import { formatDate, formatDateRange } from './formatDate'
import { KM_TO_MI } from './birdingStats'
import { TOP_SPECIES_MAX } from './hotspotReportsLocation'

export { SHOW_NEXT_LABEL, showAllLabel, showingLabel } from './lifeListsCopy'

/** N with locale grouping ("1,204"). */
export function formatCount(n: number): string {
  return n.toLocaleString('en-US')
}

function plural(n: number, one: string, many: string): string {
  return n === 1 ? one : many
}

/** Written after a name or protocol label cut at its bound (FR-13, FR-43). */
export const ELLIPSIS = '\u2026'

